"title":"Podcast Yapımı","categories":["hobby","project","writer"]},{"target":"62d466d3-f61d-48b9-8621-b55947c4a372","title":"Çizgi Roman Çizimi","categories":["hobby","project","writer"]},{"target":"eac680d2-8c4d-4596-aa24-df674988c8e8","title":"Web Tasarımı","categories":["hobby","writer","project"]},{"target":"30f04209-08e9-47f1-9073-73804e39c971","title":"Elektronik Devre Yapımı","categories":["hobby","writer","project"]},{"target":"d825ba6a-67c4-40b1-b314-910bd172c7cf","title":"Arduino Projeleri","categories":["hobby","writer","project"]},{"target":"e829a1ac-125c-42cb-8cc7-aa5c55c4d465","title":"Yoga","categories":["hobby","sport","writer"]},{"target":"f6a31541-75db-44e8-a3bc-5fda15fb2710","title":"Pilates","categories":["hobby","sport","writer"]},{"target":"6cf5d67b-ad31-42fc-9112-3ae4f6e267d0","title":"Tai Chi","categories":["hobby","sport","writer"]},{"target":"722c9459-a57b-4566-a066-c09f376b781d","title":"İp Atlama","categories":["hobby","sport","writer"]},{"target":"e0f384b8-14a2-468f-8b9c-0e0039559d30","title":"Hula Hoop","categories":["hobby","sport","writer"]},{"target":"05f0a941-f965-4e72-b5c5-894447bb2be0","title":"Şnorkelle Dalış","categories":["hobby","sport","writer"]},{"target":"379560e0-c6b4-4b5f-b7a1-a713067aafde","title":"Oryantiring","categories":["hobby","sport","writer"]},{"target":"c8351098-d59a-4ca8-b87c-323a1d33dee4","title":"Piyano","categories":["hobby","director","writer"]},{"target":"9905ff37-a0da-4247-93a5-11f06feea5af","title":"Bağlama","categories":["hobby","director","writer"]},{"target":"00c873b8-e904-42ab-93d9-ae5655044a9b","title":"Kalimba","categories":["hobby","director","writer"]},{"target":"ebbaee81-ef92-48f6-b9d7-3986b073e86f","title":"Ukulele","categories":["hobby","director","writer"]},{"target":"fcc63ff3-ad35-4a07-abd9-5a39cc5ca2b1","title":"Mızıka","categories":["hobby","director","writer"]},{"target":"b3808e31-635e-441f-8edf-484f1bc077bc","title":"Bisiklet Bakımı","categories":["hobby","writer"]},{"target":"f93b08ac-