 r jsonb; v_src uuid; v_dst uuid; v_meta jsonb; v_types jsonb; history_before text; history_after text; events_before text; events_after text;
begin
 perform pg_advisory_xact_lock(hashtext('uin-shared-catalogue-20261018'));
 select md5(jsonb_build_array((select jsonb_agg(to_jsonb(s) order by id) from public.seeds s),(select jsonb_agg(to_jsonb(w) order by id) from public.canonical_personal_intents_v38 w))::text) into history_before;
 select md5(jsonb_agg(to_jsonb(i)-'canonical_target_id'-'updated_at' order by id)::text) into events_before from public.intents i;
 for r in select value from jsonb_array_elements(payload->'pairs') loop
  v_src:=(r->>'source')::uuid;v_dst:=(r->>'destination')::uuid;
  if exists(select 1 from public.seed_catalog_items where id=(r->>'source_item')::uuid and status='merged' and merged_into_id=(r->>'destination_item')::uuid) then continue;end if;
  if not exists(select 1 from public.seed_catalog_items where id=(r->>'source_item')::uuid and canonical_target_id=v_src and status='active')
    or not exists(select 1 from public.seed_catalog_items where id=(r->>'destination_item')::uuid and canonical_target_id=v_dst and status='active') then raise exception 'Identity changed for %',r->>'title';end if;
  if exists(select 1 from public.seeds where canonical_target_id=v_src) then raise exception 'Unreviewed reference in seeds: %',v_src;end if;
  if exists(select 1 from public.canonical_personal_intents_v38 where target_id=v_src) then raise exception 'Unreviewed reference in canonical_personal_intents_v38: %',v_src;end if;
  if exists(select 1 from public.uin_event_related_cards_v72 where target_id=v_src) then raise exception 'Unreviewed reference in uin_event_related_cards_v72: %',v_src;end if;
  if exists(select 1 from public.uin_card_relations_v87 where source_target_id=v_src) then raise exception 'Unreviewed reference in uin_card_relations_v87: %',v_src;end if;
  if exists(select 1 from public.uin_card_relations_v87 where related_target_id=v_src) then raise exception 'Unreviewed reference in uin_card_relations_v87: %',v_src;end if;
  if exists(select 1 from public.uin_together_proposals_v71 where target_id=v_src) then raise exception 'Unreviewed reference in uin_together_proposals_v71: %',v_src;end if;
  if exists(select 1 from public.personal_intent_collaboration_chats where canonical_target_id=v_src) then raise exception 'Unreviewed reference in personal_intent_collaboration_chats: %',v_src;end if;
  if exists(select 1 from public.uin_club_follows where target_id=v_src) then raise exception 'Unreviewed reference in uin_club_follows: %',v_src;end if;
  if exists(select 1 from public.canonical_target_highlights where target_id=v_src) then raise exception 'Unreviewed reference in canonical_target_highlights: %',v_src;end if;
  if exists(select 1 from public.uin_card_activity_category_options_v114 where target_id=v_src) then raise exception 'Unreviewed reference in uin_card_activity_category_options_v114: %',v_src;end if;
  insert into public.uin_card_activity_options_v106(target_id,activity_id,sort_order,created_by,created_at)
   select v_dst,activity_id,sort_order,created_by,created_at from public.uin_card_activity_options_v106 where target_id=v_src on conflict do nothing;
  update public.intents set canonical_target_id=v_dst where canonical_target_id=v_src;
  update public.product_analytics_events_v81 set target_id=v_dst where target_id=v_src;
  update public.canonical_targets set editorial_metadata=coalesce(editorial_metadata,'{}')||
    jsonb_build_object('topic_aliases',coalesce(editorial_metadata->'topic_aliases','[]')||jsonb_build_array(r->>'source_title')),
    updated_at=now() where id=v_dst;
  update public.canonical_targets set editorial_metadata=coalesce(editorial_metadata,'{}')||jsonb_build_object('merged_into_target_id',v_dst,'merge_batch','uin-shared-catalogue-20261018'),updated_at=now() where id=v_src;
  update public.seed_catalog_items set status='merged',merged_into_id=(r->>'destination_item')::uuid,canonical_target_id=v_dst,updated_at=now() where id=(r->>'source_item')::uuid;
  if public.resolve_uin_card_target_v129(v_src)<>v_dst then raise exception 'Redirect failed';end if;
 end loop;
 for r in select value from jsonb_array_elements(payload->'assignments') loop
  v_dst:=(r->>'target')::uuid;
  select coalesce(editorial_metadata,'{}') into v_meta from public.canonical_targets where id=v_dst for update;
  select jsonb_agg(distinct x) into v_types from jsonb_array_elements_text(coalesce(v_meta->'content_type_ids','[]')||(r->'categories')||jsonb_build_array(v_meta->>'content_type_id')) x where x is not null;
  if jsonb_array_length(v_types)>3 then raise exception 'Too many categories for %',r->>'title';end if;
  update public.canonical_targets set
   title=coalesce(r->>'new_title',title),
   editorial_metadata=v_meta||jsonb_build_object('content_type_ids',v_types,'shared_topic_batch','uin-shared-catalogue-20261018')
     ||case when r->>'new_title' is not null then jsonb_build_object('topic_aliases',coalesce(v_meta->'topic_aliases','[]')||jsonb_build_array(title)) else '{}'::jsonb end,
   updated_at=now() where id=v_dst;
  if r->>'new_title' is not null then
   update public.seed_catalog_items set canonical_title=r->>'new_title',normalized_title=public.normalize_seed_catalog_text(r->>'new_title'),updated_at=now() where canonical_target_id=v_dst and status='active';
  end if;
 end loop;
 update public.uin_content_types set ui_labels=ui_labels||'{"wanting":"Öğrenmek isteyenler"}'::jsonb where id='writer';
 update public.uin_content_types set ui_labels=ui_labels||'{"want":"Spor yapmak istiyorum","wanting":"Spor yapmak isteyenler"}'::jsonb where id='sport';
 update public.uin_content_types set ui_labels=ui_labels||'{"want":"Hobi olarak yapmak istiyorum"}'::jsonb where id='hobby';
 select md5(jsonb_build_array((select jsonb_agg(to_jsonb(s) order by id) from public.seeds s),(select jsonb_agg(to_jsonb(w) order by id) from public.canonical_personal_intents_v38 w))::text) into history_after;
 select md5(jsonb_agg(to_jsonb(i)-'canonical_target_id'-'updated_at' order by id)::text) into events_after from public.intents i;
 if history_before is distinct from history_after then raise exception 'Personal history changed';end if;
 if events_before is distinct from events_after then raise exception 'Event content or identity changed';end if;
end;$merge$;
commit;
select uin_private.refresh_category_counts();
select 'Shared topics unified; personal records and event IDs preserved' result;
